import subprocess,json,time,re,os,uuid,hashlib
from pathlib import Path
from datetime import datetime,timezone
from zoneinfo import ZoneInfo
from urllib.parse import urlsplit
ROOT=Path('/workspace/gpc-cloud-managed-36114')
ORIGINAL_RUN=subprocess.run

def scrub(v):
 s=v.decode('utf-8',errors='replace') if isinstance(v,bytes) else str(v or '')
 def url(m):
  try:
   u=urlsplit(m[0]);return u.scheme+'://'+(u.hostname or '[redacted]')+u.path
  except ValueError:return '[redacted-url]'
 s=re.sub(r'(?:https?|ssh)://[^\s<>\"\']+',url,s)
 return re.sub(r'(?i)(authorization\s*:\s*|(?:token|password|secret)=)[^\s]+',r'\1[redacted]',s)

def persist(path,text):
 tmp=path.with_name(path.name+'.'+uuid.uuid4().hex+'.tmp')
 with tmp.open('w',encoding='utf-8') as f:
  f.write(text);f.flush();os.fsync(f.fileno())
 os.replace(tmp,path)
 fd=os.open(path.parent,os.O_DIRECTORY)
 try:os.fsync(fd)
 finally:os.close(fd)

def run(argv,*,label=None,**kw):
 name=(label or 'subprocess')+'-'+uuid.uuid4().hex
 d=ROOT/'logs'/name;d.mkdir(parents=True)
 start=datetime.now(timezone.utc);t=time.monotonic()
 record={'argv':['[private command-scoped remote config]' if re.match(r'remote\.[^=]+\.(?:url|pushurl)=',str(x)) else scrub(x) for x in argv],'cwd':str(kw.get('cwd',Path.cwd())),'started_utc':start.isoformat(),'started_moscow':start.astimezone(ZoneInfo('Europe/Moscow')).isoformat(),'returncode':None}
 persist(d/'stage.json',json.dumps(record,indent=2)+'\n')
 try:
  p=ORIGINAL_RUN(argv,**kw)
  record['returncode']=p.returncode
  persist(d/'stdout.log',scrub(p.stdout));persist(d/'stderr.log',scrub(p.stderr))
  return p
 except BaseException as e:
  record['returncode']=getattr(e,'returncode',None);record['exception_type']=type(e).__name__;record['exception']=scrub(e)
  persist(d/'stdout.log',scrub(getattr(e,'stdout',None)));persist(d/'stderr.log',scrub(getattr(e,'stderr',None)))
  raise
 finally:
  record['streams']={name:{'path':str(d/name),'sha256':hashlib.sha256((d/name).read_bytes()).hexdigest(),'bytes':(d/name).stat().st_size} for name in ['stdout.log','stderr.log'] if (d/name).exists()}
  end=datetime.now(timezone.utc);record.update(ended_utc=end.isoformat(),ended_moscow=end.astimezone(ZoneInfo('Europe/Moscow')).isoformat(),duration_seconds=round(time.monotonic()-t,6))
  persist(d/'stage.json',json.dumps(record,indent=2)+'\n')

def git(*args,label='git'):
